1	package net.officefloor.hq.app;
2	
3	import java.math.BigDecimal;
4	import java.util.Comparator;
5	import java.util.List;
6	import java.util.Set;
7	import java.util.stream.Collectors;
8	import org.springframework.web.bind.annotation.RequestParam;
9	import net.officefloor.web.ObjectResponse;
10	
11	/**
12	 * {@code GET /api/clients/statement?clientId=<id>} — a client's statement: every invoice across ALL
13	 * of that client's projects gathered in one place, each carrying how much is still due on it (its
14	 * amount minus what has been paid against it — the same money rule as {@link InvoiceDueGetLogic}),
15	 * and the OUTSTANDING TOTAL the client still owes (the sum of those dues). Derived on the server so
16	 * the money math lives in one place. Wired by {@code officefloor/rest/api/clients/statement.GET.yml}.
17	 */
18	public class ClientStatementGetLogic {
19	
20	    public void service(@RequestParam("clientId") Long clientId, ProjectRepository projects,
21	            InvoiceRepository invoices, PaymentRepository payments,
22	            ObjectResponse<ClientStatementView> response) {
23	        // The client's projects are the ones its invoices hang off (invoice -> project -> client).
24	        Set<Long> projectIds = projects.findAll().stream()
25	                .filter(p -> clientId.equals(p.getClientId()))
26	                .map(Project::getId)
27	                .collect(Collectors.toSet());
28	        List<StatementInvoiceView> rows = invoices.findAll().stream()
29	                .filter(i -> projectIds.contains(i.getProjectId()))
30	                .sorted(Comparator.comparing(Invoice::getId))
31	                .map(i -> {
32	                    BigDecimal paid = payments.findByInvoiceIdOrderByIdAsc(i.getId()).stream()
33	                            .map(Payment::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
34	                    // What is owed is the net total after any discount (Flyway V27), worked out the
35	                    // one-place way (InvoiceMoney) so the statement agrees with the dashboard and the
36	                    // invoice detail. The due — and the status derived from it — follow that total.
37	                    BigDecimal netTotal = InvoiceMoney.netTotal(i.getAmount(), i.getDiscountPct(),
38	                            i.getTaxPct());
39	                    BigDecimal due = netTotal.subtract(paid);
40	                    String status = InvoiceStatus.derive(i.getStatus(), netTotal, paid);
41	                    return new StatementInvoiceView(i.getId(), i.getProjectId(), netTotal,
42	                            paid, due, status);
43	                })
44	                .collect(Collectors.toList());
45	        BigDecimal outstanding = rows.stream().map(StatementInvoiceView::getDue)
46	                .reduce(BigDecimal.ZERO, BigDecimal::add);
47	        response.send(new ClientStatementView(clientId, rows, outstanding));
48	    }
49	
50	    /** A client's statement: its invoices, each with its due, and the total still owed across them. */
51	    public static class ClientStatementView {
52	        private final long clientId;
53	        private final List<StatementInvoiceView> invoices;
54	        private final BigDecimal outstandingTotal;
55	
56	        public ClientStatementView(long clientId, List<StatementInvoiceView> invoices,
57	                BigDecimal outstandingTotal) {
58	            this.clientId = clientId;
59	            this.invoices = invoices;
60	            this.outstandingTotal = outstandingTotal;
61	        }
62	
63	        public long getClientId() {
64	            return clientId;
65	        }
66	
67	        public List<StatementInvoiceView> getInvoices() {
68	            return invoices;
69	        }
70	
71	        public BigDecimal getOutstandingTotal() {
72	            return outstandingTotal;
73	        }
74	    }
75	
76	    /** One invoice on the statement: its amount, what has been paid, what is still due, and status. */
77	    public static class StatementInvoiceView {
78	        private final long id;
79	        private final long projectId;
80	        private final BigDecimal amount;
81	        private final BigDecimal paid;
82	        private final BigDecimal due;
83	        private final String status;
84	
85	        public StatementInvoiceView(long id, long projectId, BigDecimal amount, BigDecimal paid,
86	                BigDecimal due, String status) {
87	            this.id = id;
88	            this.projectId = projectId;
89	            this.amount = amount;
90	            this.paid = paid;
91	            this.due = due;
92	            this.status = status;
93	        }
94	
95	        public long getId() {
96	            return id;
97	        }
98	
99	        public long getProjectId() {
100	            return projectId;
101	        }
102	
103	        public BigDecimal getAmount() {
104	            return amount;
105	        }
106	
107	        public BigDecimal getPaid() {
108	            return paid;
109	        }
110	
111	        public BigDecimal getDue() {
112	            return due;
113	        }
